with with_gaps as (select *, case when lag(paid_at) over (partition by order_id order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by order_id order by paid_at, id) + interval '60' day then 1 else 0 end as is_new_burst from payments), sessionized as (select *, sum(is_new_burst) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as burst_id from with_gaps) select method, case when amount >= 1230 then 'LARGE' else 'SMALL' end as amount_tier, round(sum(is_new_burst) / nullif(count(case when method = 'promptpay' then 1 end), 0), 2) as is_new_burst_per_promptpay, min(paid_at) as first_seen from sessionized group by method, case when amount >= 1230 then 'LARGE' else 'SMALL' end order by is_new_burst_per_promptpay desc nulls first;
